changeSet.sql:
UPDATE user_reminder SET round_started_at=GREATEST(0,ack_deadline-60000)
 WHERE task_id IS NULL AND status='awaiting_confirmation' AND ack_deadline>0;
UPDATE user_reminder SET ack_deadline=round_started_at+30000
 WHERE task_id IS NULL AND status='awaiting_confirmation' AND round_started_at>0;
UPDATE user_reminder SET attempt_id=NULL WHERE task_id IS NULL AND status='scheduled';
